insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000484011', '40000000-0000-4000-8000-000000048401', 'Faça primeiro um pequeno registro das grandezas conhecidas e daquilo que a pergunta realmente pede.', 1), ('60000000-0000-4000-8000-000000484012', '40000000-0000-4000-8000-000000048401', 'O plano x igual a zero é o plano yz.', 2), ('60000000-0000-4000-8000-000000484013', '40000000-0000-4000-8000-000000048401', 'A distância perpendicular é o valor absoluto da coordenada x.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048401', '$d=1$.', 'Trate as coordenadas como informações de posição: alinhar cada eixo antes de operar evita conclusões visuais enganosas. Um plano é identificado por um ponto e um vetor normal. Na equação cartesiana, os coeficientes de x, y e z formam esse normal; substituir um ponto ou comparar normais é uma forma direta de conferir pertencimento, paralelismo e perpendicularidade. A alternativa A coincide com a relação obtida; a alternativa B ($4$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000484011', '40000000-0000-4000-8000-000000048401', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000484012', '40000000-0000-4000-8000-000000048401', 'Identifique a normal', '$n=(1,0,0).$', 2), ('70000000-0000-4000-8000-000000484013', '40000000-0000-4000-8000-000000048401', 'Meça o afastamento', 'A projeção perpendicular zera apenas a coordenada x.', 3), ('70000000-0000-4000-8000-000000484014', '40000000-0000-4000-8000-000000048401', 'Calcule', '$d=|1|=1.$', 4), ('70000000-0000-4000-8000-000000484015', '40000000-0000-4000-8000-000000048401', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000048402', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000226', 'multiple_choice', 'medium', 'published', 'Uma equipe de modelagem precisa conferir o cálculo abaixo. determine cuidadosamente a distância do ponto $P=(2,0,0)$ ao plano $x=0$.') on conflict (id) do update set subject_id = excluded.subject_id, source_id = excluded.source_id, kind = excluded.kind, difficulty = excluded.difficulty, publication_status = excluded.publication_status, statement_markdown = excluded.statement_markdown;
