insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000484061', '40000000-0000-4000-8000-000000048406', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000484062', '40000000-0000-4000-8000-000000048406', 'Identifique a normal', '$n=(1,0,0).$', 2), ('70000000-0000-4000-8000-000000484063', '40000000-0000-4000-8000-000000048406', 'Meça o afastamento', 'A projeção perpendicular zera apenas a coordenada x.', 3), ('70000000-0000-4000-8000-000000484064', '40000000-0000-4000-8000-000000048406', 'Calcule', '$d=|6|=6.$', 4), ('70000000-0000-4000-8000-000000484065', '40000000-0000-4000-8000-000000048406', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
