insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000484101', '40000000-0000-4000-8000-000000048410', 'Escolha uma alternativa apenas depois de comparar o resultado final com cada possibilidade, incluindo o sinal.', 1), ('60000000-0000-4000-8000-000000484102', '40000000-0000-4000-8000-000000048410', 'O plano z igual a zero é o plano xy.', 2), ('60000000-0000-4000-8000-000000484103', '40000000-0000-4000-8000-000000048410', 'A distância perpendicular é o valor absoluto da coordenada z.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048410', '$d=3$.', 'A resolução fica mais segura quando cada transformação é justificada e o resultado é verificado no enunciado original. Relações espaciais são determinadas pelas direções: vetores diretores descrevem retas e vetores normais descrevem planos. Comparar proporcionalidade e produto escalar permite decidir paralelismo e perpendicularidade sem depender de um desenho em perspectiva. A alternativa A coincide com a relação obtida; a alternativa B ($6$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
