insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000484121', '40000000-0000-4000-8000-000000048412', 'Escreva a relação matemática antes de substituir os valores; isso torna sinais e denominadores mais visíveis.', 1), ('60000000-0000-4000-8000-000000484122', '40000000-0000-4000-8000-000000048412', 'O plano z igual a zero é o plano xy.', 2), ('60000000-0000-4000-8000-000000484123', '40000000-0000-4000-8000-000000048412', 'A distância perpendicular é o valor absoluto da coordenada z.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048412', '$d=5$.', 'Uma boa conferência separa a ideia geométrica da conta numérica e testa o resultado na relação inicial. Relações espaciais são determinadas pelas direções: vetores diretores descrevem retas e vetores normais descrevem planos. Comparar proporcionalidade e produto escalar permite decidir paralelismo e perpendicularidade sem depender de um desenho em perspectiva. A alternativa A coincide com a relação obtida; a alternativa B ($8$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000484121', '40000000-0000-4000-8000-000000048412', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000484122', '40000000-0000-4000-8000-000000048412', 'Localize o plano', 'No plano xy, toda coordenada z vale zero.', 2), ('70000000-0000-4000-8000-000000484123', '40000000-0000-4000-8000-000000048412', 'Compare a altura', '$z_P=5.$', 3), ('70000000-0000-4000-8000-000000484124', '40000000-0000-4000-8000-000000048412', 'Aplique valor absoluto', '$d=|5|=5.$', 4), ('70000000-0000-4000-8000-000000484125', '40000000-0000-4000-8000-000000048412', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
