insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000484171', '40000000-0000-4000-8000-000000048417', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000484172', '40000000-0000-4000-8000-000000048417', 'Localize o plano', 'No plano xy, toda coordenada z vale zero.', 2), ('70000000-0000-4000-8000-000000484173', '40000000-0000-4000-8000-000000048417', 'Compare a altura', '$z_P=11.$', 3), ('70000000-0000-4000-8000-000000484174', '40000000-0000-4000-8000-000000048417', 'Aplique valor absoluto', '$d=|11|=11.$', 4), ('70000000-0000-4000-8000-000000484175', '40000000-0000-4000-8000-000000048417', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000048418', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000226', 'multiple_choice', 'hard', 'published', 'Durante uma correção de prova, considere a seguinte situação: A reta r tem diretor $d=(1,1,0)$ e o plano pi tem normal $n=(1,-1,0)$. Qual é o ângulo entre r e pi?') on conflict (id) do update set subject_id = excluded.subject_id, source_id = excluded.source_id, kind = excluded.kind, difficulty = excluded.difficulty, publication_status = excluded.publication_status, statement_markdown = excluded.statement_markdown;
