insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000484181', '40000000-0000-4000-8000-000000048418', 'Ao final, pergunte se o sinal, a direção ou a dimensão do resultado fazem sentido para a situação.', 1), ('60000000-0000-4000-8000-000000484182', '40000000-0000-4000-8000-000000048418', 'Calcule o produto escalar entre o diretor da reta e o normal do plano.', 2), ('60000000-0000-4000-8000-000000484183', '40000000-0000-4000-8000-000000048418', 'Se esse produto é zero, a reta é paralela ao plano e o ângulo reta-plano é zero.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048418', '$0^\circ$.', 'O resultado deve respeitar tanto a definição algébrica quanto a interpretação geométrica do objeto em três dimensões. Relações espaciais são determinadas pelas direções: vetores diretores descrevem retas e vetores normais descrevem planos. Comparar proporcionalidade e produto escalar permite decidir paralelismo e perpendicularidade sem depender de um desenho em perspectiva. A alternativa A coincide com a relação obtida; a alternativa B ($90^\circ$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000484181', '40000000-0000-4000-8000-000000048418', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000484182', '40000000-0000-4000-8000-000000048418', 'Calcule o produto', '$d \cdot n=1-1=0.$', 2), ('70000000-0000-4000-8000-000000484183', '40000000-0000-4000-8000-000000048418', 'Interprete', 'O diretor da reta é ortogonal ao normal do plano.', 3), ('70000000-0000-4000-8000-000000484184', '40000000-0000-4000-8000-000000048418', 'Conclua', 'A reta é paralela ao plano; assim, o menor ângulo entre eles é zero grau.', 4), ('70000000-0000-4000-8000-000000484185', '40000000-0000-4000-8000-000000048418', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
