insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000484261', '40000000-0000-4000-8000-000000048426', 'Faça primeiro um pequeno registro das grandezas conhecidas e daquilo que a pergunta realmente pede.', 1), ('60000000-0000-4000-8000-000000484262', '40000000-0000-4000-8000-000000048426', 'Compare a equação com a distância ao quadrado de um ponto fixo.', 2), ('60000000-0000-4000-8000-000000484263', '40000000-0000-4000-8000-000000048426', 'Os três termos quadráticos têm o mesmo sinal e sua soma é uma constante positiva.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048426', 'Uma esfera.', 'Trate as coordenadas como informações de posição: alinhar cada eixo antes de operar evita conclusões visuais enganosas. Quádricas são superfícies descritas por equações de segundo grau em três variáveis. A forma algébrica revela a geometria: três quadrados somados descrevem uma esfera ou elipsoide, enquanto uma variável ausente indica que a curva do plano se prolonga naquela direção. A alternativa A coincide com a relação obtida; a alternativa B (Um plano.) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
