insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048431', '$C=(1,-1,2)$.', 'Trate as coordenadas como informações de posição: alinhar cada eixo antes de operar evita conclusões visuais enganosas. Quádricas são superfícies descritas por equações de segundo grau em três variáveis. A forma algébrica revela a geometria: três quadrados somados descrevem uma esfera ou elipsoide, enquanto uma variável ausente indica que a curva do plano se prolonga naquela direção. A alternativa A coincide com a relação obtida; a alternativa B ($(-1,1,-2)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
