insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000484331', '40000000-0000-4000-8000-000000048433', 'Ao final, pergunte se o sinal, a direção ou a dimensão do resultado fazem sentido para a situação.', 1), ('60000000-0000-4000-8000-000000484332', '40000000-0000-4000-8000-000000048433', 'Na forma x menos a, a coordenada central é a.', 2), ('60000000-0000-4000-8000-000000484333', '40000000-0000-4000-8000-000000048433', 'Escreva y mais 1 como y menos menos 1.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048433', '$C=(5,-1,2)$.', 'O resultado deve respeitar tanto a definição algébrica quanto a interpretação geométrica do objeto em três dimensões. Quádricas são superfícies descritas por equações de segundo grau em três variáveis. A forma algébrica revela a geometria: três quadrados somados descrevem uma esfera ou elipsoide, enquanto uma variável ausente indica que a curva do plano se prolonga naquela direção. A alternativa A coincide com a relação obtida; a alternativa B ($(-5,1,-2)$) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000484331', '40000000-0000-4000-8000-000000048433', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000484332', '40000000-0000-4000-8000-000000048433', 'Compare o termo x', '$x-5 indica a=5.$', 2), ('70000000-0000-4000-8000-000000484333', '40000000-0000-4000-8000-000000048433', 'Observe os sinais', '$y+1=y-(-1) e z-2=z-2.$', 3), ('70000000-0000-4000-8000-000000484334', '40000000-0000-4000-8000-000000048433', 'Monte o centro', '$C=(5,-1,2).$', 4), ('70000000-0000-4000-8000-000000484335', '40000000-0000-4000-8000-000000048433', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
