insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000484361', '40000000-0000-4000-8000-000000048436', 'Faça primeiro um pequeno registro das grandezas conhecidas e daquilo que a pergunta realmente pede.', 1), ('60000000-0000-4000-8000-000000484362', '40000000-0000-4000-8000-000000048436', 'As três variáveis aparecem ao quadrado com sinal positivo.', 2), ('60000000-0000-4000-8000-000000484363', '40000000-0000-4000-8000-000000048436', 'Não há variável ausente e o lado direito é 1.', 3) on conflict (id) do update set question_id = excluded.question_id, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000048436', 'Um elipsoide.', 'Trate as coordenadas como informações de posição: alinhar cada eixo antes de operar evita conclusões visuais enganosas. Quádricas são superfícies descritas por equações de segundo grau em três variáveis. A forma algébrica revela a geometria: três quadrados somados descrevem uma esfera ou elipsoide, enquanto uma variável ausente indica que a curva do plano se prolonga naquela direção. A alternativa A coincide com a relação obtida; a alternativa B (Um cone duplo.) representa um erro de operação, direção ou interpretação comum neste tipo de exercício.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000484361', '40000000-0000-4000-8000-000000048436', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000484362', '40000000-0000-4000-8000-000000048436', 'Observe os sinais', 'Os três termos quadráticos são positivos.', 2), ('70000000-0000-4000-8000-000000484363', '40000000-0000-4000-8000-000000048436', 'Observe as variáveis', 'x, y e z aparecem; portanto, a superfície não se prolonga como um cilindro.', 3), ('70000000-0000-4000-8000-000000484364', '40000000-0000-4000-8000-000000048436', 'Classifique', 'A soma de três quadrados normalizados igual a 1 define um elipsoide.', 4), ('70000000-0000-4000-8000-000000484365', '40000000-0000-4000-8000-000000048436', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
