insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000484381', '40000000-0000-4000-8000-000000048438', 'Leia a situação', 'Identifique as informações dadas, o objeto geométrico envolvido e a grandeza solicitada.', 1), ('70000000-0000-4000-8000-000000484382', '40000000-0000-4000-8000-000000048438', 'Observe os sinais', 'Os três termos quadráticos são positivos.', 2), ('70000000-0000-4000-8000-000000484383', '40000000-0000-4000-8000-000000048438', 'Observe as variáveis', 'x, y e z aparecem; portanto, a superfície não se prolonga como um cilindro.', 3), ('70000000-0000-4000-8000-000000484384', '40000000-0000-4000-8000-000000048438', 'Classifique', 'A soma de três quadrados normalizados igual a 1 define um elipsoide.', 4), ('70000000-0000-4000-8000-000000484385', '40000000-0000-4000-8000-000000048438', 'Valide a escolha', 'Compare o resultado com a definição usada e descarte as alternativas que trocam sinais, ordem das componentes ou interpretação geométrica.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
